<?php
require_once __DIR__ . '/../src/layout.php'; require_auth();if(!role_allowed(['admin'])) exit('Acesso negado.');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$pdo->prepare('INSERT INTO users(name,email,password_hash,role,active) VALUES (?,?,?,?,1)')->execute([trim($_POST['name']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role']]);flash('success','Usuário criado.');redirect(base_url('users.php'));}
$rows=$pdo->query('SELECT id,name,email,role,active,created_at FROM users ORDER BY name')->fetchAll();render_header('Usuários');
?>
<div class="row g-3"><div class="col-lg-4"><div class="card"><div class="card-body"><h5>Novo usuário</h5><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="mb-2"><label>Nome</label><input class="form-control" name="name" required></div><div class="mb-2"><label>E-mail</label><input class="form-control" type="email" name="email" required></div><div class="mb-2"><label>Senha</label><input class="form-control" type="password" name="password" required></div><div class="mb-3"><label>Perfil</label><select class="form-select" name="role"><option value="admin">Administrador</option><option value="tecnico">Técnico</option><option value="financeiro">Financeiro</option></select></div><button class="btn btn-primary">Criar</button></form></div></div></div><div class="col-lg-8"><div class="table-wrap"><table class="table"><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Ativo</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?=$r['active']?'Sim':'Não'?></td></tr><?php endforeach;?></tbody></table></div></div></div>
<?php render_footer(); ?>
